| title = Breakdown of UN casualties|{{Flag|United Kingdom|1801}}:<br />1,109 dead<ref name="BESeoul"/><br />2,674 wounded<ref name="BESeoul">{{Cite web |last=Office of the Defence Attaché |date=30 September 2010 |title=Korean war |url=http://ukinrok.fco.gov.uk/en/about-us/working-with-korea/defence-relations/korean-war |access-date=16 February 2013 |website=British Embassy Seoul |publisher=[[Foreign and Commonwealth Office]] |archive-date=9 April 2012 |archive-url=https://web.archive.org/web/20120409080726/http://ukinrok.fco.gov.uk/en/about-us/working-with-korea/defence-relations/korean-war |url-status=dead }}</ref><br />179 MIA<ref name="ROK Web"/><br />977 POW<ref name="ROK Web"/>|{{Flag|Turkey|size=23px}}:<ref name="ROK Web"/><br />741 dead<br />2,068 wounded<br />163 MIA<br />244 POW|{{Flag|Canada|1921|size=23px}}:<br />516 dead<ref>{{Cite web |last=<!--Staff writer(s); no by-line.--> |date=11 October 2011 |title=Korean War WebQuest |url=http://www.veterans.gc.ca/eng/teach_resources/korwebquest/grp02/korsum |archive-url=https://web.archive.org/web/20130130062836/http://www.veterans.gc.ca/eng/teach_resources/korwebquest/grp02/korsum |archive-date=30 January 2013 |access-date=28 May 2013 |website=Veterans Affairs Canada |publisher=Government of Canada |quote=In Brampton, Ontario, there is a 60-metre long "Memorial Wall" of polished granite, containing individual bronze plaques which commemorate the 516 Canadian soldiers who died during the Korean War.}}<br />{{Cite web |last=<!--Staff writer(s); no by-line.--> |date=1 March 2013 |title=Canada Remembers the Korean War |url=http://www.veterans.gc.ca/eng/history/KoreaWar/koreawar_fact |archive-url=https://web.archive.org/web/20121006110456/http://www.veterans.gc.ca/eng/history/KoreaWar/koreawar_fact |archive-date=6 October 2012 |access-date=27 May 2013 |website=Veterans Affairs Canada |publisher=Government of Canada |quote=The names of 516 Canadians who died in service during the conflict are inscribed in the Korean